#!/usr/bin/env python3
"""
Ambient Context Retrieval Demo for Percept Dashboard
Offline, deterministic entity extraction and relationship building.
"""

import json
import csv
import re
from pathlib import Path
from datetime import datetime
from collections import defaultdict

# Configuration
DATA_DIR = Path('data')
OUTPUT_DIR = Path('.')

# Entity type patterns (offline, deterministic)
PERSON_NAMES = ['Avery', 'Jordan', 'Mina', 'Alex', 'Sam', 'Taylor', 'Casey', 'Riley']
ORGANIZATION_INDICATORS = ['Labs', 'Inc', 'Corp', 'Company', 'LLC', 'Ltd', 'Team']
PROJECT_INDICATORS = ['Project', 'Dashboard', 'Index', 'System', 'Platform', 'Module']
DATE_PATTERNS = [
    (r'\b(Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday)\b', 'day_of_week'),
    (r'\b(\d{4}-\d{2}-\d{2})\b', 'date'),
    (r'\b(\d{1,2}/\d{1,2}/\d{2,4})\b', 'date'),
]

def load_conversations():
    """Load conversations from JSON file."""
    conv_file = DATA_DIR / 'conversations.json'
    with open(conv_file, 'r', encoding='utf-8') as f:
        return json.load(f)

def extract_entities(text):
    """Extract entities from text using pattern matching."""
    entities = []

    # Extract people (proper names)
    for name in PERSON_NAMES:
        if name in text:
            entities.append({
                'id': f'person_{name.lower()}',
                'name': name,
                'type': 'person',
                'confidence': 0.95
            })

    # Extract organizations (names with org indicators)
    org_pattern = r'\b([A-Z][a-z]+(?:\s+[A-Z][a-z]+)*(?:\s+(?:' + '|'.join(ORGANIZATION_INDICATORS) + ')))\b'
    for match in re.finditer(org_pattern, text):
        org_name = match.group(1)
        entities.append({
            'id': f'org_{org_name.lower().replace(" ", "_")}',
            'name': org_name,
            'type': 'organization',
            'confidence': 0.9
        })

    # Extract projects (names with project indicators)
    proj_pattern = r'\b((?:Project\s+)?[A-Z][a-z]+(?:\s+[A-Z][a-z]+)*(?:\s+(?:' + '|'.join(PROJECT_INDICATORS) + '))?)\b'
    for match in re.finditer(proj_pattern, text):
        proj_name = match.group(1)
        # Avoid duplicates with organizations
        if not any(e['name'] == proj_name for e in entities):
            entities.append({
                'id': f'project_{proj_name.lower().replace(" ", "_")}',
                'name': proj_name,
                'type': 'project',
                'confidence': 0.85
            })

    # Extract dates
    for pattern, date_type in DATE_PATTERNS:
        for match in re.finditer(pattern, text):
            date_str = match.group(1)
            entities.append({
                'id': f'date_{date_str.lower().replace("-", "").replace("/", "")}',
                'name': date_str,
                'type': 'date',
                'subtype': date_type,
                'confidence': 0.9
            })

    return entities

def deduplicate_entities(all_entities):
    """Remove duplicate entities, keeping highest confidence."""
    seen = {}
    for entity in all_entities:
        entity_id = entity['id']
        if entity_id not in seen or entity['confidence'] > seen[entity_id]['confidence']:
            seen[entity_id] = entity
    return list(seen.values())

def build_relationships(conversations, entities):
    """Build relationships between entities based on co-occurrence."""
    relationships = []
    entity_map = {e['name'].lower(): e for e in entities}

    for conv in conversations:
        text_lower = conv['text'].lower()
        speaker = conv['speaker']
        conv_entities = []

        # Find entities mentioned in this conversation
        for entity in entities:
            if entity['name'].lower() in text_lower:
                conv_entities.append(entity)

        # Add speaker if they're an entity
        speaker_lower = speaker.lower()
        if speaker_lower in entity_map:
            if entity_map[speaker_lower] not in conv_entities:
                conv_entities.append(entity_map[speaker_lower])

        # Build relationships based on context
        persons = [e for e in conv_entities if e['type'] == 'person']
        projects = [e for e in conv_entities if e['type'] == 'project']
        orgs = [e for e in conv_entities if e['type'] == 'organization']
        dates = [e for e in conv_entities if e['type'] == 'date']

        # Person works_on project relationships
        for person in persons:
            for project in projects:
                rel = {
                    'source': person['id'],
                    'target': project['id'],
                    'type': 'works_on',
                    'confidence': 0.8,
                    'conversation_id': conv['id']
                }
                if rel not in relationships:
                    relationships.append(rel)

        # Project client_of organization relationships
        for project in projects:
            for org in orgs:
                rel = {
                    'source': project['id'],
                    'target': org['id'],
                    'type': 'client_of',
                    'confidence': 0.85,
                    'conversation_id': conv['id']
                }
                if rel not in relationships:
                    relationships.append(rel)

        # Person mentioned_with person relationships
        for i, p1 in enumerate(persons):
            for p2 in persons[i+1:]:
                rel = {
                    'source': p1['id'],
                    'target': p2['id'],
                    'type': 'mentioned_with',
                    'confidence': 0.75,
                    'conversation_id': conv['id']
                }
                if rel not in relationships:
                    relationships.append(rel)

        # Project deadline relationships
        for project in projects:
            for date in dates:
                rel = {
                    'source': project['id'],
                    'target': date['id'],
                    'type': 'has_deadline',
                    'confidence': 0.7,
                    'conversation_id': conv['id']
                }
                if rel not in relationships:
                    relationships.append(rel)

        # Dependency relationships (depends_on keyword)
        if 'depends on' in text_lower or 'depends on' in conv['text']:
            words = text_lower.split()
            for i, word in enumerate(words):
                if word == 'on' and i > 0:
                    # Project before "depends on" depends on project after
                    for project in projects:
                        if project['name'].lower() in text_lower[:text_lower.find('depends on')]:
                            remaining = text_lower[text_lower.find('depends on') + 11:]
                            for proj2 in projects:
                                if proj2['name'].lower() in remaining and proj2 != project:
                                    rel = {
                                        'source': project['id'],
                                        'target': proj2['id'],
                                        'type': 'depends_on',
                                        'confidence': 0.9,
                                        'conversation_id': conv['id']
                                    }
                                    if rel not in relationships:
                                        relationships.append(rel)

    return relationships

def generate_summary(entities, relationships, conversations):
    """Generate a human-readable summary."""
    summary_lines = [
        "=" * 60,
        "AMBIENT CONTEXT RETRIEVAL - SUMMARY",
        "=" * 60,
        "",
        f"Total conversations processed: {len(conversations)}",
        f"Total entities extracted: {len(entities)}",
        f"Total relationships built: {len(relationships)}",
        "",
        "-" * 40,
        "ENTITIES BY TYPE:",
        "-" * 40,
    ]

    by_type = defaultdict(list)
    for e in entities:
        by_type[e['type']].append(e['name'])

    for etype, names in sorted(by_type.items()):
        summary_lines.append(f"  {etype.capitalize()}: {', '.join(names)}")

    summary_lines.extend([
        "",
        "-" * 40,
        "KEY RELATIONSHIPS:",
        "-" * 40,
    ])

    for rel in relationships[:10]:  # Top 10 relationships
        source = next((e['name'] for e in entities if e['id'] == rel['source']), rel['source'])
        target = next((e['name'] for e in entities if e['id'] == rel['target']), rel['target'])
        summary_lines.append(f"  {source} --[{rel['type']}]--> {target}")

    summary_lines.extend([
        "",
        "-" * 40,
        "CONVERSATION TIMELINE:",
        "-" * 40,
    ])

    for conv in conversations:
        summary_lines.append(f"  [{conv['timestamp']}] {conv['speaker']}: {conv['text'][:60]}..." if len(conv['text']) > 60 else f"  [{conv['timestamp']}] {conv['speaker']}: {conv['text']}")

    summary_lines.extend([
        "",
        "=" * 60,
        f"Generated: {datetime.now().isoformat()}",
        "=" * 60,
    ])

    return "\n".join(summary_lines)

def create_context_packet(conversations, entities, relationships):
    """Create the machine-readable context packet."""
    return {
        "metadata": {
            "generated_at": datetime.now().isoformat(),
            "version": "1.0.0",
            "source": "percept-ambient-demo"
        },
        "recent_conversations": conversations,
        "resolved_entities": entities,
        "relationships": relationships,
        "relevant_history": [
            {
                "conversation_id": conv['id'],
                "timestamp": conv['timestamp'],
                "entities_mentioned": [e['id'] for e in entities if e['name'].lower() in conv['text'].lower()]
            }
            for conv in conversations
        ]
    }

def export_entities_csv(entities):
    """Export entities to CSV format."""
    csv_file = OUTPUT_DIR / 'entities.csv'
    with open(csv_file, 'w', newline='', encoding='utf-8') as f:
        writer = csv.DictWriter(f, fieldnames=['id', 'name', 'type', 'confidence', 'subtype'])
        writer.writeheader()
        for entity in entities:
            row = {
                'id': entity['id'],
                'name': entity['name'],
                'type': entity['type'],
                'confidence': entity.get('confidence', 1.0),
                'subtype': entity.get('subtype', '')
            }
            writer.writerow(row)

def main():
    """Main entry point."""
    print("Loading conversations...")
    conversations = load_conversations()
    print(f"  Loaded {len(conversations)} conversations")

    print("Extracting entities...")
    all_entities = []
    for conv in conversations:
        entities = extract_entities(conv['text'])
        all_entities.extend(entities)

    entities = deduplicate_entities(all_entities)
    print(f"  Extracted {len(entities)} unique entities")

    print("Building relationships...")
    relationships = build_relationships(conversations, entities)
    print(f"  Built {len(relationships)} relationships")

    print("Generating summary...")
    summary = generate_summary(entities, relationships, conversations)
    summary_file = OUTPUT_DIR / 'summary.txt'
    summary_file.write_text(summary, encoding='utf-8')
    print(f"  Saved to {summary_file}")

    print("Creating context packet...")
    context_packet = create_context_packet(conversations, entities, relationships)
    packet_file = OUTPUT_DIR / 'context_packet.json'
    packet_file.write_text(json.dumps(context_packet, indent=2), encoding='utf-8')
    print(f"  Saved to {packet_file}")

    print("Exporting entities CSV...")
    export_entities_csv(entities)
    csv_file = OUTPUT_DIR / 'entities.csv'
    print(f"  Saved to {csv_file}")

    print("\nDone! Output files:")
    print(f"  - {summary_file}")
    print(f"  - {packet_file}")
    print(f"  - {csv_file}")

if __name__ == '__main__':
    main()
